using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Windows;using System.Windows.Controls;
namespace FileCompass {
 internal static class SettingsRevisionTests {
  internal static int Run(string root){Directory.CreateDirectory(root);var log=new List<string>();ConfigurationDialog w=null;try{Action<bool,string> check=delegate(bool ok,string label){if(!ok)throw new Exception(label);log.Add(label);};L.ChangeLanguage("cs");w=new ConfigurationDialog(null);w.Show();w.Sections.SelectedItem=L.Text("settings.archivesSection");FluentUiTests.Children<SettingsPager>(w).Single().Select("Limity");NavigationTests.Wait(System.Threading.Tasks.Task.Delay(100));var values=FluentUiTests.Children<TextBox>(w).Where(x=>Convert.ToString(x.Tag)=="archive-limit-value").ToArray();check(values.Length==7,"seven archive limits remain editable");string[] data={"12345","512","333","4096","128","16","4"};for(int i=0;i<values.Length;i++)values[i].Text=data[i];w.SaveChanges();var saved=ArchiveSettings.Load();check(saved.MaximumItems==12345&&saved.MaximumMemoryMiB==512&&saved.MaximumSeconds==333&&saved.MaximumExtractedMiB==4096&&saved.MinimumFreeMiB==128&&saved.MaximumListingMiB==16&&saved.MaximumNesting==4,"all archive limit fields roundtrip through Save");values[0].Text="0";bool rejected=false;try{w.SaveChanges();}catch(IOException){rejected=true;}catch(ArgumentException){rejected=true;}catch(InvalidOperationException){rejected=true;}check(rejected&&ArchiveSettings.Load().MaximumItems==12345,"invalid archive limit is rejected without overwriting valid preferences");values[0].Text="12345";NextStageTests.Draw(w,Path.Combine(root,"limits.png"));var date=new DateTime(2026,11,3,12,34,0);var formatted=Convert.ToString(new PanelValueConverter().Convert(new object[]{"03.11.2026",date,1L,false,true},typeof(string),"date",System.Globalization.CultureInfo.CurrentCulture));check(formatted=="03.11.2026 12:34","panel date includes both date and time");w.Close();w=null;File.WriteAllLines(Path.Combine(root,"result.txt"),log.Concat(new[]{"PASS: "+log.Count}));return 0;}catch(Exception ex){File.WriteAllText(Path.Combine(root,"result.txt"),String.Join("\n",log)+"\n"+ex);return 1;}finally{if(w!=null)w.Close();}}
 }
}
